#!/usr/bin/env node
// Local native build for either app variant (issue #352):
//
//   node scripts/run-native.mjs <android|ios> [--dev] [-- expo run args]
//
// `--dev` builds the development variant (APP_VARIANT=development, see
// app.config.js): bundle id / package be.xeweb.famlin.dev, "Famlin (dev)" and
// the orange icon, so it installs next to the store app. Without it this is a
// plain `expo run:<platform>`, the production app id.
//
// android/ and ios/ are generated by `expo prebuild` and kept between runs,
// and `expo run` only generates them when they are missing — so after
// switching variants it would silently rebuild the previous app id. This
// script reads the id out of the existing native project and runs
// `expo prebuild --clean` first only when it doesn't match, keeping
// incremental builds fast otherwise.
//
// Never used by EAS or CI: those build from eas.json profiles, which don't set
// APP_VARIANT.

import { spawnSync } from 'child_process'
import { existsSync, readdirSync, readFileSync } from 'fs'
import { dirname, join } from 'path'
import { fileURLToPath } from 'url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')

const args = process.argv.slice(2)
const platform = args.shift()
if (platform !== 'android' && platform !== 'ios') {
  console.error('Usage: node scripts/run-native.mjs <android|ios> [--dev] [expo run args...]')
  process.exit(1)
}
const dev = args[0] === '--dev'
if (dev) args.shift()
if (args[0] === '--') args.shift()

const appId = dev ? 'be.xeweb.famlin.dev' : 'be.xeweb.famlin'

const env = { ...process.env }
if (dev) {
  env.APP_VARIANT = 'development'
  // The dev variant is never a store build, so the hidden feed scroll
  // diagnostics (#427) are compiled into it in Release configuration too —
  // the only configuration whose scroll performance means anything.
  env.EXPO_PUBLIC_SCROLL_DIAGNOSTICS ??= '1'
} else {
  delete env.APP_VARIANT
}

/** The app id(s) the existing native project was generated with, or null. */
function nativeAppIds() {
  if (platform === 'android') {
    const gradle = join(root, 'android', 'app', 'build.gradle')
    if (!existsSync(gradle)) return null
    const match = readFileSync(gradle, 'utf8').match(/applicationId\s*[=(]?\s*['"]([^'"]+)['"]/)
    return match ? [match[1]] : []
  }
  const iosDir = join(root, 'ios')
  if (!existsSync(iosDir)) return null
  const project = readdirSync(iosDir).find((name) => name.endsWith('.xcodeproj'))
  if (!project) return null
  const pbxproj = join(iosDir, project, 'project.pbxproj')
  if (!existsSync(pbxproj)) return null
  const ids = [...readFileSync(pbxproj, 'utf8').matchAll(/PRODUCT_BUNDLE_IDENTIFIER = "?([^";]+)"?;/g)]
  return ids.map((m) => m[1])
}

function run(cmdArgs) {
  console.log(`> ${dev ? 'APP_VARIANT=development ' : ''}npx ${cmdArgs.join(' ')}`)
  const result = spawnSync('npx', cmdArgs, {
    cwd: root,
    env,
    stdio: 'inherit',
    shell: process.platform === 'win32',
  })
  if (result.status !== 0) process.exit(result.status ?? 1)
}

const ids = nativeAppIds()
if (ids !== null && !ids.includes(appId)) {
  console.log(
    `Native ${platform} project was generated for ${ids.join(', ') || 'another app id'}; regenerating it for ${appId}.`
  )
  run(['expo', 'prebuild', '--clean', '--platform', platform])
}

run(['expo', `run:${platform}`, ...args])
